<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const map=L.map('map').setView([44.67,34.41],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);let mode='direct',lines=[],targetMarker=null,launchMarker=null;const now=new Date();const local=d=>new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);dtime.value=local(now);btime.value=local(now);fs.value=local(now);fe.value=local(new Date(now.getTime()+6*3600000));
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.getElementById(b.dataset.panel).classList.add('active');mode=b.dataset.panel});
function status(s,err=false){document.getElementById('status').textContent=s;document.getElementById('status').style.color=err?'#c00':''}function progress(v,show=true){const p=document.getElementById('progress');p.style.display=show?'block':'none';p.firstElementChild.style.width=Math.max(0,Math.min(100,v))+'%'}function clearLines(){lines.forEach(x=>map.removeLayer(x));lines=[]}function line(points,color='#1f6feb',weight=3){if(!points||points.length<2)return null;const l=L.polyline(points.map(p=>[p.lat,p.lon]),{color,weight}).addTo(map);lines.push(l);return l}function fitAll(){if(lines.length){const g=L.featureGroup(lines);map.fitBounds(g.getBounds().pad(.15))} }function showResult(html){document.getElementById('result').innerHTML=html||''}
function markPoint(kind,la,lo){const m=L.marker([la,lo]).addTo(map);if(kind==='targetMarker'){if(targetMarker)map.removeLayer(targetMarker);targetMarker=m}else{if(launchMarker)map.removeLayer(launchMarker);launchMarker=m}}
function pick(m){mode=m;status('Кликните по карте');map.once('click',e=>{const la=e.latlng.lat.toFixed(6),lo=e.latlng.lng.toFixed(6);if(m==='direct'){dlat.value=la;dlon.value=lo}else if(m==='back'){blat.value=la;blon.value=lo}else if(m==='target'){tlat.value=la;tlon.value=lo;markPoint('targetMarker',+la,+lo)}else{clat.value=la;clon.value=lo;markPoint('launchMarker',+la,+lo)}status('Точка установлена')})}
</script></body></html>
